export const FORGE_PROJECT_IDS = Object.freeze(Object.keys(symbols));
export function forgeProjectIcon(projectId) {
 if (!Object.hasOwn(symbols, projectId)) throw new RangeError('Unknown forge project: ' + projectId);
 return symbols[projectId];
}
